import React, { useState, useEffect } from "react";
import { useNavigate, useLocation } from "react-router-dom";
import { GAME_TYPES } from "../constants/questions";
import { storage, STORAGE_KEYS } from "../utils/storage";
import { getRandomQuestions } from "../utils/questionManager";
import "./GamePage.css";

const GamePage = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const { userDetails, gameType } = location.state || {};

  const [currentQuestion, setCurrentQuestion] = useState(0);
  const [timer, setTimer] = useState(0);
  const [score, setScore] = useState(0);
  const [userAnswer, setUserAnswer] = useState("");
  const [selectedOption, setSelectedOption] = useState("");
  const [questions, setQuestions] = useState([]);
  const [gameState, setGameState] = useState("INITIAL_COUNTDOWN");
  const [countdown, setCountdown] = useState(3);
  const [startTime, setStartTime] = useState(0);
  const [isCorrectAnswer, setIsCorrectAnswer] = useState(false);
  const [selectedCells, setSelectedCells] = useState([]);
  const [crosswordSelection, setCrosswordSelection] = useState({
    start: null,
    end: null,
  });

  // Initialize questions using question manager
  useEffect(() => {
    const selectedQuestions = getRandomQuestions(gameType, 6);
    setQuestions(selectedQuestions);
  }, [gameType]);

  // Game state machine - FIXED: Added proper dependencies
  useEffect(() => {
    let timer;

    switch (gameState) {
      case "INITIAL_COUNTDOWN":
        if (countdown > 0) {
          timer = setTimeout(() => setCountdown(countdown - 1), 1000);
        } else {
          startQuestion();
        }
        break;

      case "QUESTION":
        if (
          timer > 0 &&
          !gameState.includes("FEEDBACK") &&
          !gameState.includes("COMPLETED")
        ) {
          timer = setTimeout(() => setTimer(timer - 1), 1000);
        } else if (timer === 0) {
          handleTimeUp();
        }
        break;

      case "FEEDBACK":
        timer = setTimeout(() => {
          moveToNextQuestion();
        }, 2000);
        break;

      default:
        break;
    }

    return () => clearTimeout(timer);
  }, [gameState, countdown, timer, currentQuestion, questions.length]); // Added dependencies

  const startQuestion = () => {
    setGameState("QUESTION");
    setStartTime(Date.now());
    const questionTimer = gameType === GAME_TYPES.CROSSWORD ? 60 : 10;
    setTimer(questionTimer);
    setSelectedCells([]);
    setCrosswordSelection({ start: null, end: null });
    setIsCorrectAnswer(false); // Reset correctness state
    setUserAnswer(""); // Reset user answer
    setSelectedOption(""); // Reset selected option
  };

  const handleTimeUp = () => {
    setIsCorrectAnswer(false);
    setGameState("FEEDBACK");
    // Highlight correct answers for crossword ONLY when time's up
    if (gameType === GAME_TYPES.CROSSWORD) {
      highlightCorrectAnswers();
    }
  };

  const highlightCorrectAnswers = () => {
    const currentQ = questions[currentQuestion];
    if (!currentQ || !currentQ.words) return;

    const correctCells = [];

    currentQ.words.forEach((wordObj) => {
      const { word, row, col, direction } = wordObj;
      for (let i = 0; i < word.length; i++) {
        if (direction === "across") {
          correctCells.push(`${row},${col + i}`);
        } else {
          correctCells.push(`${row + i},${col}`);
        }
      }
    });

    setSelectedCells(correctCells.map((cell) => ({ cell, status: "timeup" })));
  };

  const calculateScore = () => {
    const timeTaken = (Date.now() - startTime) / 1000;
    const baseScore = 100;
    const timeBonus = Math.max(0, 10 - timeTaken) * 10;
    return baseScore + timeBonus;
  };

  // Crossword selection handlers
  const handleCellMouseDown = (row, col) => {
    if (gameState !== "QUESTION") return;
    setCrosswordSelection({ start: { row, col }, end: { row, col } });
  };

  const handleCellMouseEnter = (row, col) => {
    if (gameState !== "QUESTION" || !crosswordSelection.start) return;
    setCrosswordSelection((prev) => ({ ...prev, end: { row, col } }));
  };

  const handleCellMouseUp = () => {
    if (gameState !== "QUESTION" || !crosswordSelection.start) return;

    const { start, end } = crosswordSelection;
    const selectedWord = getSelectedWord(start, end);

    if (selectedWord && selectedWord.length > 1) {
      // Only check if word has more than 1 letter
      checkCrosswordAnswer(selectedWord);
    }

    setCrosswordSelection({ start: null, end: null });
  };

  const getSelectedWord = (start, end) => {
    const currentQ = questions[currentQuestion];
    if (!currentQ || !currentQ.grid) return null;

    const grid = currentQ.grid;

    // Determine direction and get word
    if (start.row === end.row) {
      // Horizontal selection
      const minCol = Math.min(start.col, end.col);
      const maxCol = Math.max(start.col, end.col);
      let word = "";
      for (let col = minCol; col <= maxCol; col++) {
        if (grid[start.row] && grid[start.row][col]) {
          word += grid[start.row][col];
        }
      }
      return word;
    } else if (start.col === end.col) {
      // Vertical selection
      const minRow = Math.min(start.row, end.row);
      const maxRow = Math.max(start.row, end.row);
      let word = "";
      for (let row = minRow; row <= maxRow; row++) {
        if (grid[row] && grid[row][start.col]) {
          word += grid[row][start.col];
        }
      }
      return word;
    }
    return null;
  };

  const checkCrosswordAnswer = (selectedWord) => {
    const currentQ = questions[currentQuestion];
    if (!currentQ || !currentQ.words) return;

    const isCorrect = currentQ.words.some(
      (wordObj) => wordObj.word === selectedWord.toUpperCase()
    );

    setIsCorrectAnswer(isCorrect);

    if (isCorrect) {
      const questionScore = calculateScore();
      setScore((prev) => prev + questionScore);

      // Highlight correct selection
      const { start, end } = crosswordSelection;
      const newSelectedCells = [];

      if (start.row === end.row) {
        const minCol = Math.min(start.col, end.col);
        const maxCol = Math.max(start.col, end.col);
        for (let col = minCol; col <= maxCol; col++) {
          newSelectedCells.push({
            cell: `${start.row},${col}`,
            status: "correct",
          });
        }
      } else {
        const minRow = Math.min(start.row, end.row);
        const maxRow = Math.max(start.row, end.row);
        for (let row = minRow; row <= maxRow; row++) {
          newSelectedCells.push({
            cell: `${row},${start.col}`,
            status: "correct",
          });
        }
      }

      setSelectedCells((prev) => [...prev, ...newSelectedCells]);

      // Auto move to feedback after correct answer
      setTimeout(() => {
        setGameState("FEEDBACK");
      }, 1000);
    } else {
      // Highlight wrong selection
      const { start, end } = crosswordSelection;
      const newSelectedCells = [];

      if (start.row === end.row) {
        const minCol = Math.min(start.col, end.col);
        const maxCol = Math.max(start.col, end.col);
        for (let col = minCol; col <= maxCol; col++) {
          newSelectedCells.push({
            cell: `${start.row},${col}`,
            status: "wrong",
          });
        }
      } else {
        const minRow = Math.min(start.row, end.row);
        const maxRow = Math.max(start.row, end.row);
        for (let row = minRow; row <= maxRow; row++) {
          newSelectedCells.push({
            cell: `${row},${start.col}`,
            status: "wrong",
          });
        }
      }

      setSelectedCells((prev) => [...prev, ...newSelectedCells]);
    }
  };

  const handleSubmit = () => {
    if (gameState !== "QUESTION") return;

    const currentQ = questions[currentQuestion];
    if (!currentQ) return;

    let isCorrect = false;

    if (gameType === GAME_TYPES.JUMBLE) {
      isCorrect =
        userAnswer.trim().toUpperCase() === currentQ.correct.toUpperCase();
    } else if (gameType === GAME_TYPES.MCQ) {
      isCorrect = selectedOption === currentQ.correct;
    }

    setIsCorrectAnswer(isCorrect);

    if (isCorrect) {
      const questionScore = calculateScore();
      setScore((prev) => prev + questionScore);
    }

    setGameState("FEEDBACK");
  };

  const moveToNextQuestion = () => {
    if (currentQuestion < questions.length - 1) {
      setCurrentQuestion((prev) => prev + 1);
      setGameState("INITIAL_COUNTDOWN");
      setCountdown(3);
    } else {
      completeGame();
    }
  };

  const completeGame = () => {
    setGameState("COMPLETED");

    const gameData = {
      userDetails,
      gameType,
      score,
      timestamp: new Date().toISOString(),
      totalQuestions: questions.length,
    };

    const existingScores = storage.getItem(STORAGE_KEYS.SCORES) || [];
    const existingUserData = storage.getItem(STORAGE_KEYS.USER_DATA) || [];

    storage.setItem(STORAGE_KEYS.SCORES, [...existingScores, gameData]);
    storage.setItem(STORAGE_KEYS.USER_DATA, [...existingUserData, userDetails]);
  };

  const getOptionClassName = (option) => {
    if (gameState === "QUESTION") {
      return `option-btn ${selectedOption === option ? "selected" : ""}`;
    }

    if (option === questions[currentQuestion]?.correct) {
      return "option-btn correct-answer";
    } else if (option === selectedOption && !isCorrectAnswer) {
      return "option-btn wrong-answer";
    } else {
      return "option-btn";
    }
  };

  const getCrosswordCellClassName = (row, col) => {
    const cellKey = `${row},${col}`;
    const selectedCell = selectedCells.find((sc) => sc.cell === cellKey);

    if (selectedCell) {
      return `crossword-cell ${selectedCell.status}`;
    }

    const isInSelection = isCellInSelection(row, col);
    if (isInSelection) {
      return "crossword-cell selecting";
    }

    return "crossword-cell";
  };

  const isCellInSelection = (row, col) => {
    if (!crosswordSelection.start || !crosswordSelection.end) return false;

    const { start, end } = crosswordSelection;
    const minRow = Math.min(start.row, end.row);
    const maxRow = Math.max(start.row, end.row);
    const minCol = Math.min(start.col, end.col);
    const maxCol = Math.max(start.col, end.col);

    return row >= minRow && row <= maxRow && col >= minCol && col <= maxCol;
  };

  const renderQuestion = () => {
    if (!questions.length || currentQuestion >= questions.length) return null;

    const question = questions[currentQuestion];
    if (!question) return null;

    switch (gameType) {
      case GAME_TYPES.JUMBLE:
        return (
          <div className="jumble-question">
            <h2>Unscramble the Word</h2>
            <div className="jumbled-word">{question.jumbled}</div>
            <input
              type="text"
              value={userAnswer}
              onChange={(e) => setUserAnswer(e.target.value)}
              placeholder="Enter the correct word"
              className="answer-input"
              disabled={gameState !== "QUESTION"}
            />
          </div>
        );

      case GAME_TYPES.MCQ:
        return (
          <div className="mcq-question">
            <h2>{question.question}</h2>
            <div className="options-container">
              {question.options.map((option, index) => (
                <button
                  key={index}
                  className={getOptionClassName(option)}
                  onClick={() =>
                    gameState === "QUESTION" && setSelectedOption(option)
                  }
                  disabled={gameState !== "QUESTION"}
                >
                  {option}
                </button>
              ))}
            </div>
          </div>
        );

      case GAME_TYPES.CROSSWORD:
        return (
          <div className="crossword-question">
            <h2>Crossword Puzzle</h2>
            <div className="crossword-container">
              <div
                className="crossword-grid"
                onMouseLeave={() =>
                  setCrosswordSelection({ start: null, end: null })
                }
              >
                {question.grid.map((row, rowIndex) => (
                  <div key={rowIndex} className="crossword-row">
                    {row.map((cell, colIndex) => (
                      <div
                        key={colIndex}
                        className={getCrosswordCellClassName(
                          rowIndex,
                          colIndex
                        )}
                        onMouseDown={() =>
                          handleCellMouseDown(rowIndex, colIndex)
                        }
                        onMouseEnter={() =>
                          handleCellMouseEnter(rowIndex, colIndex)
                        }
                        onMouseUp={handleCellMouseUp}
                      >
                        {cell}
                      </div>
                    ))}
                  </div>
                ))}
              </div>
              <div className="crossword-clues">
                <div className="clues-section">
                  <h3>Across</h3>
                  {question.clues.across.map((clue, index) => (
                    <div key={index} className="clue-item">
                      <span className="clue-number">{clue.number}.</span>
                      <span className="clue-text">{clue.clue}</span>
                    </div>
                  ))}
                </div>
                <div className="clues-section">
                  <h3>Down</h3>
                  {question.clues.down.map((clue, index) => (
                    <div key={index} className="clue-item">
                      <span className="clue-number">{clue.number}.</span>
                      <span className="clue-text">{clue.clue}</span>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>
        );

      default:
        return null;
    }
  };

  const renderFeedback = () => {
    if (gameState !== "FEEDBACK") return null;

    return (
      <div
        className={`answer-feedback ${
          isCorrectAnswer ? "correct" : "incorrect"
        }`}
      >
        {isCorrectAnswer ? "✓ Correct!" : "✗ Incorrect!"}
        {!isCorrectAnswer && gameType !== GAME_TYPES.CROSSWORD && (
          <div style={{ marginTop: "10px", fontSize: "1rem" }}>
            Correct answer: {questions[currentQuestion]?.correct}
          </div>
        )}
      </div>
    );
  };

  if (gameState === "INITIAL_COUNTDOWN") {
    return (
      <div className="countdown-container">
        <div className="countdown-display">
          <h1 className="countdown-number">{countdown}</h1>
          <p className="countdown-text">Game Starts In</p>
        </div>
      </div>
    );
  }

  if (gameState === "COMPLETED") {
    return (
      <div className="game-completed">
        <h1>Game Completed!</h1>
        <p>Your Score: {score}</p>
        <button
          onClick={() =>
            navigate("/score-popup", {
              state: { score, userDetails, gameType },
            })
          }
        >
          See Results
        </button>
      </div>
    );
  }

  return (
    <div className="game-page-container">
      <div className="game-header">
        <div className="user-info">
          <span>
            <strong>Name:</strong> {userDetails?.name || "Unknown"}
          </span>
          <span>
            <strong>School:</strong> {userDetails?.school || "Unknown"}
          </span>
        </div>
        <div className="game-info">
          <span>
            <strong>Question:</strong> {currentQuestion + 1}/{questions.length}
          </span>
          <span className="timer">
            <strong>Time:</strong> {timer}s
          </span>
          <span>
            <strong>Score:</strong> {score}
          </span>
        </div>
      </div>

      <div className="question-area">
        {renderQuestion()}
        {renderFeedback()}
      </div>

      {gameState === "QUESTION" && gameType !== GAME_TYPES.CROSSWORD && (
        <div className="submit-section">
          <button
            className="submit-btn"
            onClick={handleSubmit}
            disabled={!userAnswer && !selectedOption}
          >
            Submit Answer
          </button>
        </div>
      )}
    </div>
  );
};

export default GamePage;
